## Why This Is Asked
Tests ability to combine subarray maxima with partition DP, requiring both maximization and reconstruction of multiple intervals. It exercises careful indexing and boundary handling.

## Key Concepts
- Non-overlapping subarrays with a cap k
- Precomputation of maxSub for O(1) subarray maxima
- 2D DP with reconstruction pointers
- Time/space tradeoffs and edge cases (k=0, equal values)

## Code Example
```javascript
function maxValueWithKSubarrays(A, k) {
  const n = A.length;
  const maxSub = Array.from({length: n}, () => Array(n).fill(0));
  for (let l = 0; l < n; l++) {
    let m = -Infinity;
    for (let r = l; r < n; r++) {
      m = Math.max(m, A[r]);
      maxSub[l][r] = m;
    }
  }
  const dp = Array.from({length: n+1}, () => Array(k+1).fill(0));
  const take = Array.from({length: n+1}, () => Array(k+1).fill(-1));
  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      let best = dp[i-1][t];
      let bestJ = -1;
      for (let j = 1; j <= i; j++) {
        const val = maxSub[j-1][i-1] + dp[j-1][t-1];
        if (val > best) { best = val; bestJ = j; }
      }
      dp[i][t] = best; take[i][t] = bestJ;
    }
  }
  const res = [];
  let i = n, t = k;
  while (t > 0 && i > 0) {
    const j = take[i][t];
    if (j === -1) break;
    res.push([j-1, i-1]);
    i = j - 1;
    t--;
  }
  res.reverse();
  return {value: dp[n][k], subarrays: res};
}
```

## Why This Is Asked
Tests ability to design an optimized DP on a circular constraint and track the number of optimal solutions.

## Key Concepts
- DP on linear sequences with spacing (dp[i] = max(dp[i-1], dp[i-d] + v[i]))
- Reducing circularity to two linear cases (include first vs exclude first)
- Counting distinct optimal subsets with tie handling (sum counts when equal)

## Code Example
```javascript
function linearDP(arr, d){
  const n = arr.length; const dp = Array(n+1).fill(0); const ways = Array(n+1).fill(0);
  dp[0] = 0; ways[0] = 1;
  for(let i=1;i<=n;i++){
    const take = arr[i-1] + (i-d>=0 ? dp[i-d] : 0);
    const skip = dp[i-1];
    if(take>skip){ dp[i]=take; ways[i]=(i-d>=0 ? ways[i-d] : 1); }
    else if(take<skip){ dp[i]=skip; ways[i]=ways[i-1]; }
    else { dp[i]=skip; ways[i] = ((i-d>=0 ? ways[i-d] : 1) + ways[i-1]); }
  }
  return [dp[n], ways[n]];
}

function maxCircular(v, d){
  const [bestA, cntA] = linearDP(v.slice(1), d); // exclude first
  const n = v.length;
  const seg = (n > 2*d-1) ? v.slice(d, n-d+1) : [];
  const [bestBseg, cntBseg] = seg.length ? linearDP(seg, d) : [0,1];
  const bestB = v[0] + bestBseg;
  if(bestA > bestB) return [bestA, cntA];
  if(bestB > bestA) return [bestB, cntBseg];
  return [bestA, cntA + cntBseg];
}
```

